/* -------------------------------------------------------------------------- */

static void handle_sigchld(void) {
    /* Reap any dead children; update awk/child bookkeeping. */
    int status;
    pid_t pid;
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        if (pid == g_awk_pid) {
            g_awk_pid = -1;
            if (g_awk_in >= 0) { close(g_awk_in); g_awk_in = -1; }
            fprintf(stderr, "%s: status process terminated\n", g_progname);
        } else if (pid == g_child_pid) {
            g_child_pid = -1;
        }
    }
