        }
        if (r < 0) {
            if (errno == EINTR) continue;
            if (n == 0) return 0;
            buf[n] = '\0';
            return 1;
        }
        if (c == '\n') {
            buf[n] = '\0';
            return 1;
        }
        buf[n++] = c;
    }
    buf[n] = '\0';
    return 1;
}

/* -------------------------------------------------------------------------- */

static int follow_symlinks(void) {
    return getenv("ENTR_FOLLOW_SYMLINK") != NULL;
}

static int ev_trace_enabled(void) {
    return getenv("EV_TRACE") != NULL;
}

static int inotify_workaround(void) {
    return getenv("ENTR_INOTIFY_WORKAROUND") != NULL;
}

/* -------------------------------------------------------------------------- */

static char *xstrdup(const char *s) {
    char *c = strdup(s);
    if (!c) { perror("strdup"); exit(1); }
    return c;
}

static void *xrealloc(void *p, size_t n) {
    void *r = realloc(p, n);
    if (!r) { perror("realloc"); exit(1); }
    return r;
}

static char *path_dirname_dup(const char *p) {
    char *copy = xstrdup(p);
    char *d = dirname(copy);
    char *r = xstrdup(d);
    free(copy);
    return r;
}

static char *path_basename_dup(const char *p) {
    char *copy = xstrdup(p);
    char *b = basename(copy);
    char *r = xstrdup(b);
    free(copy);
    return r;
}

/* Collect filenames from sibling entries for later diffing. */
static int list_directory(const char *dirpath, char ***out_names) {
    DIR *d = opendir(dirpath);
    if (!d) {
        *out_names = NULL;
        return 0;
    }
    int cap = 16, n = 0;
    char **names = malloc(cap * sizeof *names);
    if (!names) { closedir(d); *out_names = NULL; return 0; }
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0)
            continue;
        if (opt_dir < 2 && de->d_name[0] == '.')
            continue;
        if (n == cap) {
            cap *= 2;
            names = xrealloc(names, cap * sizeof *names);
        }
        names[n++] = xstrdup(de->d_name);
    }
    closedir(d);
    *out_names = names;
    return n;
}

static void free_names(char **names, int n) {
    if (!names) return;
    for (int i = 0; i < n; i++) free(names[i]);
    free(names);
}

/* Check if a new entry has appeared in the directory compared to `old` list. */
static int directory_changed(const char *dirpath, char **old, int oldn) {
    char **cur = NULL;
    int curn = list_directory(dirpath, &cur);
    int changed = 0;
    /* For speed we don't need sorted lists; use simple O(n*m) compare. */
    for (int i = 0; i < curn && !changed; i++) {
        int found = 0;
        for (int j = 0; j < oldn; j++) {
            if (strcmp(cur[i], old[j]) == 0) { found = 1; break; }
        }
        if (!found) { changed = 1; break; }
    }
    for (int i = 0; i < oldn && !changed; i++) {
        int found = 0;
        for (int j = 0; j < curn; j++) {
            if (strcmp(old[i], cur[j]) == 0) { found = 1; break; }
        }
        if (!found) { changed = 1; break; }
    }
    free_names(cur, curn);
    return changed;
}

/* -------------------------------------------------------------------------- */

static int infd;  /* inotify fd */

static int add_file_watch(const char *path) {
    uint32_t mask = IN_CLOSE_WRITE | IN_MODIFY | IN_ATTRIB
                  | IN_DELETE_SELF | IN_MOVE_SELF;
    if (!follow_symlinks())
        mask |= IN_DONT_FOLLOW;
    int wd = inotify_add_watch(infd, path, mask);
    if (wd < 0) {
        errmsg("cannot open '%s': %s", path, strerror(errno));
        return -1;
    }
    return wd;
}

static int add_dir_watch(const char *path) {
    uint32_t mask = IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO
                  | IN_ATTRIB;
    if (!follow_symlinks())
        mask |= IN_DONT_FOLLOW;
    int wd = inotify_add_watch(infd, path, mask);
    if (wd < 0) {
        errmsg("cannot open '%s': %s", path, strerror(errno));
        return -1;
    }
    return wd;
}

/* Look up the watch entry corresponding to a wd. */
static watch_t *find_watch(int wd) {
    for (int i = 0; i < n_watches; i++) {
        if (watches[i].wd == wd)
            return &watches[i];
    }
    return NULL;
}

/* Check whether a dir entry is already tracked (so we don't double-add). */
static int have_watch_for_path(const char *p) {
    for (int i = 0; i < n_watches; i++) {
        if (strcmp(watches[i].path, p) == 0)
            return 1;
    }
    return 0;
}

/* -------------------------------------------------------------------------- */

/* Current absolute path of the file that triggered an event; used for /_ . */
static char g_trigger_path[PATH_MAX];

static void set_trigger(const char *path) {
    char *abs = realpath(path, NULL);
    if (abs) {
        strncpy(g_trigger_path, abs, sizeof g_trigger_path - 1);
        g_trigger_path[sizeof g_trigger_path - 1] = '\0';
        free(abs);
    } else {
        strncpy(g_trigger_path, path, sizeof g_trigger_path - 1);
        g_trigger_path[sizeof g_trigger_path - 1] = '\0';
    }
}

/* -------------------------------------------------------------------------- */

/* The user's command line: argv passed to exec.  The original argv is
 * templated — occurrences of `/_` are substituted with the trigger path at
 * execution time.  We keep both the original template and a scratch copy. */
static char **user_argv_template;
static int    user_argc;
static char **user_argv_scratch;

/* Build a concrete argv from the template, with a single /_ replacement. */
static void build_argv(void) {
    int replaced = 0;
    for (int i = 0; i < user_argc; i++) {
        if (!replaced && strcmp(user_argv_template[i], "/_") == 0) {
            user_argv_scratch[i] = g_trigger_path;
            replaced = 1;
        } else {
            user_argv_scratch[i] = user_argv_template[i];
        }
    }
    user_argv_scratch[user_argc] = NULL;
}

/* -------------------------------------------------------------------------- */

static void clear_screen(void) {
    if (opt_clear == 0) return;
    fputs("\033[2J", stdout);
    if (opt_clear >= 2)
        fputs("\033[3J", stdout);
    fputs("\033[H", stdout);
    fflush(stdout);
}

/* -------------------------------------------------------------------------- */

/* Make the status directory and default script if needed. */
static char *status_script_path(void) {
    static char buf[PATH_MAX];
    const char *env = getenv("ENTR_STATUS_SCRIPT");
    if (env && *env) {
        snprintf(buf, sizeof buf, "%s", env);
    } else {
        const char *home = getenv("HOME");
        if (!home) home = "";
        snprintf(buf, sizeof buf, "%s/.entr/status.awk", home);
    }
    return buf;
}

static void ensure_status_script(void) {
    char *p = status_script_path();
    if (access(p, F_OK) == 0) return;
    /* Create parent directory if possible. */
    char *parent = path_dirname_dup(p);
    mkdir(parent, 0750);
    free(parent);
    FILE *f = fopen(p, "w");
    if (!f) {
        errmsg("open: %s", strerror(errno));
        return;
    }
    fputs(
        "# http://eradman.com/entrproject/status-filters.html\n"
        "/^signal/ { print $3, \"terminated by signal\", $2; }\n"
        "/^exit/ { print $3, \"returned exit code\", $2; }\n",
        f);
    fclose(f);
    fprintf(stdout, "entr: created '%s'\n", p);
    fflush(stdout);
}

/* Spawn awk as the status filter process.  Returns 0 on success. */
static int start_awk_status(void) {
    char *script = status_script_path();
    int p[2];
    if (pipe(p) < 0) { perror("pipe"); return -1; }
    pid_t pid = fork();
    if (pid < 0) { perror("fork"); close(p[0]); close(p[1]); return -1; }
    if (pid == 0) {
        dup2(p[0], 0);
        close(p[0]);
        close(p[1]);
        if (opt_status == 1)
            execlp("awk", "awk", "-F", "|", "-f", script, "-S", (char*)NULL);
        else
            execlp("awk", "awk", "-F", "|", "-f", script, (char*)NULL);
        _exit(127);
    }
    close(p[0]);
    g_awk_pid = pid;
    g_awk_in  = p[1];
    fcntl(g_awk_in, F_SETFD, FD_CLOEXEC);
    return 0;
}

static const char *basename_c(const char *p) {
    const char *s = strrchr(p, '/');
    return s ? s + 1 : p;
}

static void status_report(int wstatus, const char *cmdname) {
    if (!opt_status || g_awk_in < 0) return;
    const char *kind;
    int code;
    if (WIFEXITED(wstatus)) {
        kind = "exit";
        code = WEXITSTATUS(wstatus);
    } else if (WIFSIGNALED(wstatus)) {
        kind = "signal";
        code = WTERMSIG(wstatus);
    } else {
        return;
    }
    char msg[256];
    int n = snprintf(msg, sizeof msg, "%s|%d|%s\n", kind, code, cmdname);
    if (n > 0) {
        ssize_t w = write(g_awk_in, msg, n);
        (void)w;
    }
}

/* -------------------------------------------------------------------------- */

/* Spawn the user's utility.  Returns the pid of the spawned process or -1. */
static pid_t spawn_utility(int background) {
    pid_t pid = fork();
    if (pid < 0) { perror("fork"); return -1; }
    if (pid == 0) {
        /* Put restart-mode child in its own process group. */
        if (opt_restart)
            setpgid(0, 0);
        /* Reset signal handlers. */
        signal(SIGINT,  SIG_DFL);
        signal(SIGTERM, SIG_DFL);
        signal(SIGHUP,  SIG_DFL);
        signal(SIGCHLD, SIG_DFL);
        signal(SIGPIPE, SIG_DFL);

        /* stdin handling. */
        if (background) {
            int nullfd = open("/dev/null", O_RDONLY);
            if (nullfd >= 0) { dup2(nullfd, 0); close(nullfd); }
        } else if (!opt_nointeractive) {
            int tty = open("/dev/tty", O_RDONLY);
            if (tty >= 0) { dup2(tty, 0); close(tty); }
        }

        /* Close extra fds. */
        closelog();
        if (g_awk_in >= 0) close(g_awk_in);

        build_argv();
        if (opt_shell) {
            const char *sh = getenv("SHELL");
            if (!sh || !*sh) sh = "/bin/sh";
            /* Build argv: sh -c <arg1> <trigger> [extra args...] */
            int extra = user_argc - 1;
            char **a = calloc(extra + 4, sizeof *a);
            a[0] = (char*)sh;
            a[1] = (char*)"-c";
            a[2] = user_argv_scratch[0];
            a[3] = g_trigger_path;
            for (int i = 1; i < user_argc; i++)
                a[i + 3] = user_argv_scratch[i];
            a[user_argc + 3] = NULL;
            execvp(sh, a);
            fprintf(stderr, "%s: exec %s: %s\n", g_progname, sh, strerror(errno));
            _exit(127);
        } else {
            execvp(user_argv_scratch[0], user_argv_scratch);
            fprintf(stderr, "%s: exec %s: %s\n", g_progname,
                    user_argv_scratch[0], strerror(errno));
            _exit(127);
        }
    }
    if (opt_restart)
        setpgid(pid, pid);
    return pid;
}

static void wait_for_child(pid_t pid) {
    int status;
    while (1) {
        pid_t r = waitpid(pid, &status, 0);
        if (r < 0) {
            if (errno == EINTR) {
                /* Signals may have arrived; drain self-pipe. */
                unsigned char c;
                while (read(g_sig_pipe[0], &c, 1) > 0) { }
                continue;
            }
            break;
        }
        if (r == pid)
            break;
    }
    g_child_pid = -1;
    /* Determine cmd name for status output. */
    const char *cmdname;
    if (opt_shell) {
        const char *sh = getenv("SHELL");
        if (!sh || !*sh) sh = "/bin/sh";
        cmdname = basename_c(sh);
    } else {
        cmdname = basename_c(user_argv_template[0]);
    }
    status_report(status, cmdname);
    if (WIFEXITED(status))
        g_final_status = WEXITSTATUS(status);
    else if (WIFSIGNALED(status))
        g_final_status = 128 + WTERMSIG(status);
    else
        g_final_status = 1;
}

/* Kill a running restart-mode child and wait for it. */
static void terminate_child(void) {
    if (g_child_pid <= 0) return;
    int sig = restart_signal();
    kill(-g_child_pid, sig);
    /* Wait for it. */
    int status;
    waitpid(g_child_pid, &status, 0);
    g_child_pid = -1;
}

/* Foreground (blocking) execution used when -r is not set. */
static void exec_blocking(void) {
    if (opt_clear) clear_screen();
    pid_t pid = spawn_utility(0);
    if (pid < 0) return;
    g_child_pid = pid;
    wait_for_child(pid);
}

/* Background execution used when -r is set. */
static void exec_restartable(void) {
    terminate_child();
    if (opt_clear) clear_screen();
    pid_t pid = spawn_utility(1);
    if (pid < 0) return;
    g_child_pid = pid;
}

/* -------------------------------------------------------------------------- */

/* Parse stdin file list, stat each, and populate the watch list. */
static void load_watches(void) {
    char line[LINE_MAX_BUF];
    int have_regular = 0;
    int fd = 0;

    while (read_line(fd, line, sizeof line)) {
        if (line[0] == '\0') continue;
        struct stat st;
        int rc = follow_symlinks() ? stat(line, &st) : lstat(line, &st);
        if (rc < 0) {
            errmsg("unable to stat '%s'", line);
            continue;
        }
        int is_dir = S_ISDIR(st.st_mode);
        int is_reg = S_ISREG(st.st_mode);
        int is_lnk = S_ISLNK(st.st_mode);
        if (!is_reg && !is_dir && !is_lnk) continue;
        if (n_watches >= MAX_FILES) continue;
        watches = xrealloc(watches, (n_watches + 1) * sizeof *watches);
        memset(&watches[n_watches], 0, sizeof watches[n_watches]);
        watches[n_watches].path   = xstrdup(line);
        watches[n_watches].is_dir = is_dir;
        n_watches++;
        if (is_reg || is_lnk) have_regular = 1;
    }

    if (!have_regular) {
        errmsg("No regular files to watch");
        exit(1);
    }

    /* Set up inotify. */
    infd = inotify_init1(IN_CLOEXEC);
    if (infd < 0) { perror("inotify_init1"); exit(1); }

    if (ev_trace_enabled()) {
        long om = sysconf(_SC_OPEN_MAX);
        fprintf(stderr, "open_max: %ld\n", om);
        if (inotify_workaround())
            fprintf(stderr, "%s: broken inotify workaround enabled\n", g_progname);
    } else if (inotify_workaround()) {
        fprintf(stderr, "%s: broken inotify workaround enabled\n", g_progname);
    }

    /* Pre-trigger: first file triggers /_ replacement. */
    for (int i = 0; i < n_watches; i++) {
        if (!watches[i].is_dir) {
            set_trigger(watches[i].path);
            break;
        }
    }

    /* Install file watches. */
    for (int i = 0; i < n_watches; i++) {
        if (watches[i].is_dir) {
            watches[i].wd = add_dir_watch(watches[i].path);
            if (watches[i].wd >= 0)
                watches[i].entry_count =
                    list_directory(watches[i].path, &watches[i].entries);
        } else {
            watches[i].wd = add_file_watch(watches[i].path);
        }
    }

    /* If -d was specified, add directory watches for parents of regular files. */
    if (opt_dir) {
        int saved = n_watches;
        for (int i = 0; i < saved; i++) {
            if (watches[i].is_dir) continue;
            char *parent = path_dirname_dup(watches[i].path);
            if (have_watch_for_path(parent)) { free(parent); continue; }
            watches = xrealloc(watches, (n_watches + 1) * sizeof *watches);
            memset(&watches[n_watches], 0, sizeof watches[n_watches]);
            watches[n_watches].path   = parent;
            watches[n_watches].is_dir = 1;
            watches[n_watches].wd     = add_dir_watch(parent);
            if (watches[n_watches].wd >= 0)
                watches[n_watches].entry_count =
                    list_directory(parent, &watches[n_watches].entries);
            n_watches++;
        }
    }
}

/* -------------------------------------------------------------------------- */

/* Re-open a file watch in case it was replaced (write-and-rename). */
static void reopen_watch(watch_t *w) {
    inotify_rm_watch(infd, w->wd);
    w->wd = add_file_watch(w->path);
    if (w->wd < 0) {
        /* vanished — signal an error and exit. */
        exit(1);
    }
}

/* -------------------------------------------------------------------------- */

static void drain_signals(int *quit, int *sigchld) {
    unsigned char c;
    while (read(g_sig_pipe[0], &c, 1) > 0) {
        if (c == SIGINT || c == SIGTERM || c == SIGHUP)
            *quit = 1;
        if (c == SIGCHLD)
            *sigchld = 1;
    }
}

/* Returns non-zero to trigger re-exec. */
static int handle_inotify(int *dir_altered) {
    char buf[65536] __attribute__((aligned(8)));
    int trigger = 0;
    ssize_t n = read(infd, buf, sizeof buf);
    if (n <= 0) return 0;
    for (char *p = buf; p < buf + n; ) {
        struct inotify_event *ev = (struct inotify_event *)p;
        p += sizeof *ev + ev->len;

        watch_t *w = find_watch(ev->wd);
        if (!w) continue;

        if (ev_trace_enabled()) {
            const char *name = (ev->len > 0) ? ev->name : basename_c(w->path);
            fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n",
                    (int)(w - watches), n_watches,
                    ev->mask & 0xffffu,
                    w->is_dir ? 'd' : 'r',
                    w->is_dir ? 040755 : 0100644,
                    name);
        }

        if (w->is_dir) {
            /* Determine whether an entry visible to us changed. */
            if (ev->len > 0) {
                if (opt_dir < 2 && ev->name[0] == '.')
                    continue;
            }
            if (ev->mask & (IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO)) {
                if (directory_changed(w->path, w->entries, w->entry_count))
                    *dir_altered = 1;
            }
        } else {
            if (ev->mask & (IN_MODIFY | IN_CLOSE_WRITE | IN_ATTRIB)) {
                set_trigger(w->path);
                trigger = 1;
            }
            if (ev->mask & (IN_IGNORED | IN_DELETE_SELF | IN_MOVE_SELF)) {
                /* File went away or was replaced — try to reopen. */
                struct stat st;
                int rc = follow_symlinks() ? stat(w->path, &st)
                                           : lstat(w->path, &st);
                if (rc < 0) {
                    errmsg("cannot open '%s': %s", w->path, strerror(errno));
                    exit(1);
                }
                reopen_watch(w);
                set_trigger(w->path);
                trigger = 1;
            }
        }
    }
    return trigger;
}

/* -------------------------------------------------------------------------- */

static void handle_sigchld(void) {
    /* Reap any dead children; update awk/child bookkeeping. */
    int status;
    pid_t pid;
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        if (pid == g_awk_pid) {
            g_awk_pid = -1;
            if (g_awk_in >= 0) { close(g_awk_in); g_awk_in = -1; }
            fprintf(stderr, "%s: status process terminated\n", g_progname);
        } else if (pid == g_child_pid) {
            g_child_pid = -1;
        }
    }
}

/* Refresh list of known directory entries after handling dir alter. */
static void refresh_dir_entries(void) {
    for (int i = 0; i < n_watches; i++) {
        if (!watches[i].is_dir) continue;
        free_names(watches[i].entries, watches[i].entry_count);
        watches[i].entries = NULL;
        watches[i].entry_count =
            list_directory(watches[i].path, &watches[i].entries);
    }
}

/* -------------------------------------------------------------------------- */

/* Put terminal into a mode that lets us read single keys. */
static void setup_tty(void) {
    if (opt_nointeractive) return;
    if (!isatty(STDIN_FILENO)) return;
    if (tcgetattr(STDIN_FILENO, &g_saved_termios) == 0) {
        g_have_saved_termios = 1;
        struct termios t = g_saved_termios;
        t.c_lflag &= ~(ICANON | ECHO);
        t.c_cc[VMIN]  = 1;
        t.c_cc[VTIME] = 0;
        tcsetattr(STDIN_FILENO, TCSANOW, &t);
        atexit(restore_terminal);
    }
}

static int tty_fd = -1;

static int open_tty(void) {
    if (opt_nointeractive) return -1;
    int fd = open("/dev/tty", O_RDONLY);
    if (fd >= 0) {
        struct termios t;
        if (tcgetattr(fd, &t) == 0) {
            struct termios s = t;
            s.c_lflag &= ~(ICANON | ECHO);
            s.c_cc[VMIN] = 1;
            s.c_cc[VTIME] = 0;
            tcsetattr(fd, TCSANOW, &s);
            /* Restore is on exit via atexit — but we use separate fd, not stdin. */
        }
    }
    return fd;
}

/* -------------------------------------------------------------------------- */

static void main_loop(void) {
    if (!opt_postpone) {
        if (opt_restart)
            exec_restartable();
        else
            exec_blocking();

        if (opt_exit) {
            exit(g_final_status);
        }
    }

    tty_fd = open_tty();

    for (;;) {
        struct pollfd pfds[3];
        int nfds = 0;
        pfds[nfds].fd = infd;         pfds[nfds].events = POLLIN; nfds++;
        pfds[nfds].fd = g_sig_pipe[0]; pfds[nfds].events = POLLIN; nfds++;
        if (tty_fd >= 0) {
            pfds[nfds].fd = tty_fd; pfds[nfds].events = POLLIN; nfds++;
        }
        int pr = poll(pfds, nfds, -1);
        if (pr < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            exit(1);
        }

        int quit = 0, sigchld = 0;
        if (pfds[1].revents & POLLIN) drain_signals(&quit, &sigchld);
        if (quit) exit(0);
        if (sigchld) handle_sigchld();

        int dir_altered = 0;
        int trigger = 0;
        if (pfds[0].revents & POLLIN)
            trigger = handle_inotify(&dir_altered);

        if (dir_altered) {
            fprintf(stderr, "%s: directory altered\n", g_progname);
            exit(2);
        }

        int kb_exec = 0, kb_quit = 0;
        if (tty_fd >= 0 && nfds >= 3 && (pfds[2].revents & POLLIN)) {
            char c;
            ssize_t nr = read(tty_fd, &c, 1);
            if (nr > 0) {
                if (c == ' ') kb_exec = 1;
                else if (c == 'q') kb_quit = 1;
            }
        }
        if (kb_quit) exit(0);

        if (trigger || kb_exec) {
            if (opt_restart) {
                exec_restartable();
            } else {
                /* Drain any pending inotify events if not -a. */
                if (!opt_all) {
                    for (;;) {
                        char drain[65536];
                        struct pollfd p2 = {infd, POLLIN, 0};
                        int r = poll(&p2, 1, 0);
                        if (r <= 0) break;
                        ssize_t rd = read(infd, drain, sizeof drain);
                        if (rd <= 0) break;
                    }
                }
                exec_blocking();
                if (opt_exit)
                    exit(g_final_status);
            }
        }
    }
}

/* -------------------------------------------------------------------------- */

int main(int argc, char *argv[]) {
    /* argv[0] basename for diagnostics. */
    const char *p0 = argv[0];
    const char *slash = strrchr(p0, '/');
    g_progname = slash ? slash + 1 : p0;

    int ch;
    while ((ch = getopt(argc, argv, "acdhnprsxz")) != -1) {
        switch (ch) {
            case 'a': opt_all++; break;
            case 'c': opt_clear++; break;
            case 'd': opt_dir++; break;
            case 'h': usage_long(); exit(1);
            case 'n': opt_nointeractive++; break;
            case 'p': opt_postpone++; break;
            case 'r': opt_restart++; break;
            case 's': opt_shell++; break;
            case 'x': opt_status++; break;
            case 'z': opt_exit++; break;
            default:
                usage_short();
                exit(1);
        }
    }
    argv += optind;
    argc -= optind;
    if (argc <= 0) { usage_short(); exit(1); }

    if (opt_shell && argc > 1) {
        errmsg("-s requires commands to be formatted as a single argument");
        exit(1);
    }

    user_argc = argc;
    user_argv_template = argv;
    user_argv_scratch = calloc(argc + 1, sizeof *user_argv_scratch);
    if (!user_argv_scratch) { perror("calloc"); exit(1); }

    /* Defaults. */
    setenv("PAGER", "/bin/cat", 0);

    if (opt_status)
        ensure_status_script();

    install_signals();
    load_watches();

    if (opt_status) {
        if (start_awk_status() < 0) {
            /* fall through; status reporting disabled. */
        }
    }

    setup_tty();

    main_loop();
    return 0;
}
ENDCFILE
